/* Generated by vite.config.js. This worker only caches the built application shell. */
const CACHE_NAME = __CACHE_NAME__
const PRECACHE_URLS = __PRECACHE_URLS__
const CACHE_PREFIX = 'smart-tourism-shell-'

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_NAME)
    await cache.addAll(PRECACHE_URLS)
  })())
})

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const cacheNames = await caches.keys()
    await Promise.all(cacheNames
      .filter(name => name.startsWith(CACHE_PREFIX) && name !== CACHE_NAME)
      .map(name => caches.delete(name)))
    await self.clients.claim()
  })())
})

self.addEventListener('message', event => {
  if (event.data?.type === 'SKIP_WAITING') self.skipWaiting()
})

self.addEventListener('fetch', event => {
  const request = event.request
  if (request.method !== 'GET') return

  const url = new URL(request.url)
  if (url.origin !== self.location.origin) return
  // Never cache backend data or actions; POI, statistics, AI, and routing stay online-only.
  if (url.pathname.startsWith('/api/')) return

  if (request.mode === 'navigate') {
    event.respondWith((async () => {
      try {
        const response = await fetch(request)
        if (response.ok) {
          const cache = await caches.open(CACHE_NAME)
          await cache.put('/index.html', response.clone())
        }
        return response
      } catch {
        return (await caches.open(CACHE_NAME)).match('/index.html')
      }
    })())
    return
  }

  const isPrecached = PRECACHE_URLS.includes(url.pathname)
  const isBuiltAsset = /^\/assets\/[^/]+\.(?:css|js|png|svg|webp|woff2?)$/i.test(url.pathname)
  if (!isPrecached && !isBuiltAsset) return

  event.respondWith((async () => {
    const cache = await caches.open(CACHE_NAME)
    const cached = await cache.match(url.pathname)
    if (cached) return cached
    const response = await fetch(request)
    if (response.ok && response.type === 'basic') await cache.put(url.pathname, response.clone())
    return response
  })())
})
